local k = 0
local function run(e)
	local m = #s
	local x0, y0, z0 = e.x, e.y, e.z
	Player:changPlayerMoveType(e.eventobjid, 1)
	Game:msgBox("正在生成请耐心等待！")
	for k = m, 1, -1 do
		Block:setBlockAll(x0 + s[k][1], y0 + s[k][2], z0 + s[k][3], s[k][4], s[k][5])
